-- PT111-S3-Q5. Batch 09.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT111-S3-Q5$batch09$ AND q.stimulus=$batch09$Parent: I had tried without success to get my young child to brush her teeth. I had hoped that she would imitate me, or that she would be persuaded by reason to brush her teeth. Then, I made a point of brushing her teeth for her immediately before reading her a story before her naps and at night. After several weeks, when I would pick up a storybook at these times, she began automatically to retrieve her toothbrush and brush her teeth herself.$batch09$ AND q.prompt=$batch09$The parent's experience with the child most closely conforms to which one of the following generalizations?$batch09$ AND q.correct_choice=$batch09$B$batch09$) THEN RAISE EXCEPTION 'Question changed: PT111-S3-Q5'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch09$PT111-S3-Q5$batch09$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT111-S3-Q5'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT111-S3-Q5$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Situation$batch09$, $batch09$The parent tried setting an example and tried reasoning, and neither worked. Then the parent brushed the child's teeth every time, right before a story. After several weeks, picking up a storybook was enough to make the child brush unprompted.$batch09$), (1, $batch09$Evaluate$batch09$, $batch09$The story eliminates two methods, imitation and reason, and credits a third: the same routine repeated until it became automatic. Whatever generalization fits has to favor habit over those other means.$batch09$), (2, $batch09$Goal$batch09$, $batch09$Children adopt a behavior through habit and repetition more readily than through example or reason.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT111-S3-Q5$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$The parent hoped the child would imitate. It didn't work.$batch09$), ($batch09$B$batch09$, $batch09$Example and reason failed, and repetition worked. "More readily than through other means" is exactly what the parent saw.$batch09$), ($batch09$C$batch09$, $batch09$Reasoning failed with this child, but we don't know why. Maybe the child understood and just didn't care. "Too young to understand" makes a claim about children's minds that the story never supports.$batch09$), ($batch09$D$batch09$, $batch09$The child didn't imitate the parent. And D's contrast between imitation and reason misses the method that actually worked.$batch09$), ($batch09$E$batch09$, $batch09$Nothing suggests the child wanted attention or acted against expectations on purpose.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT111-S3-Q5$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
